export const fableExpansionDrafts = [
  cultural({code:'S131',id:'la-guineu-i-el-corb',title:'La guineu i el corb',grade:'3',level:'middle',universeIds:['faules-mon'],
    introduction:'Comprensió oral. La guineu i el corb. Una faula de la tradició d’Isop.',
    summary:'Un corb es prepara per esmorzar dalt d’un arbre. A sota, una guineu té moltes ganes de parlar amb ell.',
    context:'En les faules, els animals poden parlar i fer coses que ens recorden les persones. Escolta aquesta adaptació i fixa’t en què vol cadascun dels dos personatges.',
    editorialFocus:'Faules del món. 3r intermèdia: dos personatges i una escena contínua; sis preguntes duals sobre accions, causa i intenció inferida. La diferència entre els elogis i el propòsit de la guineu es reconstrueix amb el relat, sense sentència moral.',
    factualSources:[{label:'Library of Congress, The Fox & the Crow, dins The Aesop for Children (1919), amb il·lustracions de Milo Winter. Contrast de l’argument tradicional: formatge al bec, elogis, cant i pèrdua del menjar.',url:'https://read.gov/aesop/027.html'}],
    illustrationBrief:'Clariana de bosc amb una guineu caminant i un corb volant a certa distància. Cap formatge, cap bec obert per cantar ni gest d’elogi; no representar l’ordre dels fets o el desenllaç.',
    transcript:[d('Adaptació original en català de l’argument isòpic contrastat a la Library of Congress. El cistell inicial i les rèpliques són recreacions de Sentit; no és una traducció del text de 1919. S’ometen el títol de reina dels ocells i el comentari final de la guineu sobre el seny del corb. Una sola veu per al narrador i els diàlegs citats. Entrada musical breu; mantenir una única base molt suau sota tot el relat.'),
      s('esmorzar','Narrador','Un matí, un corb va trobar un tros de formatge al costat d’un cistell abandonat. El va agafar amb el bec i va volar fins a una branca, ben amunt. Abans de menjar-se’l, va mirar al voltant. A baix, una guineu s’havia aturat amb el nas enlaire.'),
      s('salutacio','Narrador','La guineu tenia gana. Va donar una volta al tronc, però la branca era massa alta per arribar-hi. Es va asseure i va saludar: «Bon dia! Quin goig que fas dalt de l’arbre!» El corb va abaixar el cap per mirar-la. Es va quedar callat, amb el formatge ben subjectat al bec.'),
      s('elogis','Narrador','«Tens unes plomes que brillen molt», va continuar la guineu. «I unes ales ben grosses! Si la teva veu és tan bonica com les teves plomes, t’hauria de sentir tot el bosc. Em cantaries una cançó?»'),
      s('cant','Narrador','El corb va estirar el coll. Li agradava tant que parlessin bé d’ell que es va oblidar del que duia al bec. Va obrir-lo per cantar i el formatge va caure a terra.'),
      s('final','Narrador','La guineu el va agafar de seguida i se’l va empassar. El corb va fer un salt a la branca i va mirar el terra buit. «Jo encara no havia acabat la cançó!», va cridar. Però la guineu ja s’allunyava entre els arbres.'),
      d('Mantenir els elogis en la mateixa veu, amb intenció amable; no caricaturitzar el corb. Cap efecte de caiguda, mossegada o cant que respongui per si sol. Després de l’última paraula, pujar la base dos segons i fer la fosa final.')],
    items:[
      q('bec','Què porta el corb al bec quan arriba a la branca?','Un tros de formatge.',['Un tros de formatge.','Una branca petita.','Un tros de pa.','Una fruita del cistell.'],'a','El corb agafa el formatge amb el bec abans de volar fins a l’arbre.',[e('esmorzar','un tros de formatge'),e('esmorzar','El va agafar amb el bec i va volar fins a una branca')]),
      q('arribar','Quin problema troba la guineu quan dona la volta al tronc?','La branca del corb és massa alta per arribar-hi.',['El corb ja s’ha menjat el formatge.','El cistell és massa pesant per moure’l.','La branca del corb és massa alta per arribar-hi.','El corb ha volat fins a un altre arbre.'],'c','La guineu veu el menjar, però no pot arribar a la branca.',[e('salutacio','la branca era massa alta per arribar-hi')]),
      q('demanar','Què demana la guineu al corb després de parlar de les seves plomes?','Que li canti una cançó.',['Que baixi a buscar el cistell.','Que li canti una cançó.','Que li ensenyi on ha trobat el formatge.','Que voli per damunt dels arbres.'],'b','La petició de cantar arriba després dels elogis a les plomes i les ales.',[e('elogis','Em cantaries una cançó?')]),
      q('oblidar','Per què el corb s’oblida del que duu al bec?','Perquè li agrada molt que la guineu parli bé d’ell.',['Perquè té pressa per tornar al cistell.','Perquè intenta veure un altre corb.','Perquè li sembla que el formatge ha caigut.','Perquè li agrada que la guineu parli bé d’ell.'],'d','Els elogis fan que el corb deixi de pensar en el seu esmorzar.',[e('cant','Li agradava tant que parlessin bé d’ell que es va oblidar del que duia al bec')]),
      q('caiguda','Què fa que el formatge caigui a terra?','El corb obre el bec per cantar.',['El corb obre el bec per cantar.','La guineu sacseja el tronc de l’arbre.','El corb baixa volant fins al cistell.','La guineu fa caure la branca.'],'a','El formatge deixa d’estar subjectat quan el corb obre el bec.',[e('cant','Va obrir-lo per cantar i el formatge va caure a terra')]),
      q('intencio','Què vol aconseguir la guineu fent cantar el corb?','Que deixi anar el formatge per poder-se’l menjar.',['Que els altres ocells s’acostin a escoltar.','Que el corb li indiqui el camí del bosc.','Que deixi anar el formatge per poder-se’l menjar.','Que el corb l’ajudi a pujar a la branca.'],'c','La gana, l’intent d’arribar a la branca i la rapidesa amb què agafa el formatge permeten inferir el propòsit dels elogis.',[e('salutacio','La guineu tenia gana'),e('salutacio','la branca era massa alta per arribar-hi'),e('final','La guineu el va agafar de seguida i se’l va empassar')],2)
    ]}),
  cultural({code:'S132',id:'la-llebre-i-la-tortuga',title:'La llebre i la tortuga',grade:'3',level:'easy',universeIds:['faules-mon'],
    seconds: 85, status: 'ready-for-review', reviewStatus: 'audio-review',
    audio: './assets/audio/s132-mixed-v1.mp3', tracks: { introduction: './assets/audio/s132-mixed-v1-intro.mp3', body: './assets/audio/s132-mixed-v1-cos.mp3' },
    fragment: { start: 6.265000000000001, seconds: 78 },
    introduction:'Comprensió oral. La llebre i la tortuga. Una faula de la tradició d’Isop.',
    summary:'Una llebre i una tortuga decideixen fer una cursa pel camí del bosc. Cadascuna la comença al seu ritme.',
    context:'Escoltaràs una faula en què dos animals fan una cursa. Fixa’t en què fa cadascun durant el recorregut i en com arriben al final.',
    editorialFocus:'Faules del món. 3r accessible: dos personatges, una cursa i una seqüència lineal. Cinc preguntes duals amb causes pròximes i una explicació global del resultat. Sense temps numèrics, tercers personatges o moral final.',
    factualSources:[{label:'Library of Congress, The Hare & the Tortoise, dins The Aesop for Children (1919), amb il·lustracions de Milo Winter. Contrast de la cursa, el son de la llebre i la marxa contínua de la tortuga.',url:'https://read.gov/aesop/025.html'}],
    illustrationBrief:'Camí de bosc ample amb una llebre i una tortuga preparades per començar a caminar. Sense línia d’arribada, arbre on dormir, avantatge entre animals ni cap resultat de la cursa.',
    transcript:[d('Adaptació original en català de la faula isòpica. Les dues corredores acorden directament el recorregut; s’omet la guineu que fa d’àrbitre a la versió consultada. L’arribada al roure i els diàlegs són recreació de Sentit. Narració i rèpliques amb una sola veu. Entrada breu d’una base pròpia de la peça, molt suau i contínua sota la parla.'),
      s('repte','Narrador','Una llebre es reia de la tortuga perquè caminava molt a poc a poc. Cada vegada que es trobaven al camí, li preguntava si encara era al mateix lloc. Aquell matí, la tortuga es va aturar. «Vols fer una cursa amb mi?», li va preguntar. La llebre va esclatar a riure, però va acceptar.'),
      s('sortida','Narrador','Van triar el camí que arribava fins a un roure gros. Qui toqués primer el tronc guanyaria. Es van posar l’una al costat de l’altra i van sortir alhora. La llebre va arrencar a córrer. En pocs salts, va deixar la tortuga molt enrere.'),
      s('descans','Narrador','Quan ja no la veia, la llebre es va estirar a l’ombra. «Tinc temps de sobres», va pensar. «Quan la tortuga arribi fins aquí, em posaré a córrer una altra vegada.» Va recolzar el cap sobre les potes i es va adormir.'),
      s('caminar','Narrador','La tortuga va continuar caminant. Feia passes curtes, una darrere l’altra, sense aturar-se. Va passar pel costat de la llebre adormida i va seguir cap al roure.'),
      s('arribada','Narrador','Quan la llebre va obrir els ulls, la tortuga ja era a prop del tronc. La llebre es va aixecar d’un bot i va córrer tan de pressa com va poder. Però va arribar just a temps de veure com la tortuga tocava el roure amb una pota.'),
      d('Cap soroll de roncs, cursa o arribada que substitueixi les paraules. Mantenir la mateixa base molt suau, sense accelerar-la quan corre la llebre. Deixar acabar pota, pujar la base dos segons i fondre-la.')],
    items:[
      q('meta','Què han de fer per guanyar la cursa?','Tocar primer el tronc del roure.',['Passar primer pel costat de la llebre.','Tocar primer el tronc del roure.','Arribar primer a l’ombra del camí.','Tornar primer al lloc de sortida.'],'b','Les dues corredores acorden que tocar el tronc marca l’arribada.',[e('sortida','Qui toqués primer el tronc guanyaria')]),
      q('confianca','Per què la llebre s’atura a descansar?','Perquè ha deixat la tortuga molt enrere i creu que té temps de sobres.',['Perquè la tortuga li ha demanat que l’esperi.','Perquè s’ha fet mal en una pota mentre corria.','Perquè pensa que ja ha tocat el roure de l’arribada.','Perquè ha deixat la tortuga enrere i creu que té molt temps.'],'d','La llebre dona per fet que podrà reprendre la cursa quan la tortuga s’acosti.',[e('sortida','va deixar la tortuga molt enrere'),e('descans','Tinc temps de sobres')],2),
      q('continuar','Què fa la tortuga mentre la llebre dorm?','Continua caminant sense aturar-se i passa pel seu costat.',['Continua caminant i passa pel seu costat.','S’estira a descansar al costat de la llebre.','Torna enrere per començar la cursa de nou.','S’atura per despertar la llebre.'],'a','La tortuga manté la marxa i avança més enllà del lloc on dorm la llebre.',[e('caminar','sense aturar-se. Va passar pel costat de la llebre adormida i va seguir cap al roure')]),
      q('despertar','On és la tortuga quan la llebre es desperta?','Ja és a prop del tronc del roure.',['Encara és al lloc de sortida.','És al costat de la llebre, esperant-la.','Ja és a prop del tronc del roure.','Torna pel camí després de la cursa.'],'c','La llebre es desperta quan la tortuga està a punt d’arribar.',[e('arribada','Quan la llebre va obrir els ulls, la tortuga ja era a prop del tronc')]),
      q('resultat','Com aconsegueix guanyar la tortuga si camina més a poc a poc?','Continua avançant mentre la llebre s’atura i s’adorm.',['Troba un camí més curt fins al roure.','Continua avançant mentre la llebre s’adorm.','Fa que la llebre torni al lloc de sortida.','Aprèn a córrer més de pressa que la llebre.'],'b','La marxa contínua de la tortuga li permet aprofitar el temps que la llebre passa adormida.',[e('descans','es va adormir'),e('caminar','La tortuga va continuar caminant'),e('arribada','la tortuga tocava el roure amb una pota')],2)
    ]}),
  cultural({code:'S133',id:'el-vent-i-el-sol',title:'El vent i el Sol',grade:'4',level:'easy',universeIds:['faules-mon'],
    introduction:'Comprensió oral. El vent i el Sol. Una faula de la tradició d’Isop.',
    summary:'El vent i el Sol discuteixen sobre qui té més força. Un viatger que passa pel camí els dona una idea per fer una prova.',
    context:'En aquesta faula el vent i el Sol parlen com si fossin persones. Escolta la prova que es proposen i observa com reacciona el viatger amb cadascun.',
    editorialFocus:'Faules del món. 4t accessible: un mateix objectiu i dos intents successius. Sis preguntes duals sobre condició, reaccions i causa del resultat. La comparació es limita a aquesta prova; no es locuta una lliçó general.',
    factualSources:[{label:'Library of Congress, The North Wind & the Sun, dins The Aesop for Children (1919), amb il·lustracions de Milo Winter. Contrast dels dos intents i les reaccions del viatger.',url:'https://read.gov/aesop/143.html'}],
    illustrationBrief:'Paisatge de turons amb un camí, un Sol expressiu i una figura de vent als núvols. El viatger pot aparèixer molt lluny; no mostrar com subjecta o es treu la roba, ni el resultat de la prova.',
    transcript:[d('Adaptació original en català de la faula isòpica. S’utilitza un abric quotidià en lloc de la capa del testimoni anglès; es conserven la prova, els dos intents i les reaccions oposades del viatger. Diàlegs recreats per a Sentit i una sola veu narradora. Entrada musical breu; una única base molt suau es manté durant tots dos intents, sense donar una pista musical del guanyador.'),
      s('discussio','Narrador','El vent del nord i el Sol discutien sobre qui tenia més força. El vent feia moure les branques i deia: «Mira com tremolen els arbres quan bufo!» El Sol estava a punt de respondre quan van veure un home que avançava pel camí. Duia un abric llarg ben cordat.'),
      s('prova','Narrador','«Fem una prova», va proposar el Sol. «Guanyarà qui aconsegueixi que aquell home es tregui l’abric.» El vent va voler començar. El Sol es va amagar darrere d’un núvol i el vent va bufar amb força sobre el camí.'),
      s('vent','Narrador','L’home es va aturar. Les vores de l’abric voleiaven i el fred li entrava per les mànigues. Va ajuntar les dues vores amb les mans i se les va prémer contra el cos. El vent va bufar encara més fort. L’home es va agafar l’abric amb més força i va continuar caminant, amb el cap baix.'),
      s('sol','Narrador','Finalment, el vent va parar. El Sol va sortir de darrere del núvol i va començar a escalfar el camí. L’home va aixecar el cap i va afluixar les mans. Al cap d’una estona, es va descordar l’abric. El Sol continuava escalfant i l’home es va eixugar el front.'),
      s('final','Narrador','«Quina calor!», va dir el viatger. Es va treure l’abric, se’l va posar al braç i va anar a seure a l’ombra d’un arbre. El vent va mirar l’abric que l’home duia al braç. Durant una estona, no va dir res.'),
      d('Narrar els dos intents amb intensitat vocal moderada, sense vent enregistrat o crescendos sota dades clau. Conservar la mateixa base sota la parla. Després de res, pujar-la dos segons i acabar amb una fosa.')],
    items:[
      q('condicio','Què ha d’aconseguir el guanyador de la prova?','Que el viatger es tregui l’abric.',['Que el viatger canviï de camí.','Que el viatger s’aturi sota el núvol.','Que el viatger es tregui l’abric.','Que el viatger camini més de pressa.'],'c','Acorden una acció concreta del viatger per decidir el resultat.',[e('prova','Guanyarà qui aconsegueixi que aquell home es tregui l’abric')]),
      q('primer','Qui fa el primer intent?','El vent.',['El vent.','El Sol.','El viatger.','El vent i el Sol alhora.'],'a','El vent demana començar i bufa abans que actuï el Sol.',[e('prova','El vent va voler començar')]),
      q('reaccio','Què fa l’home quan el vent bufa encara més fort?','S’agafa l’abric amb més força.',['Es treu l’abric i se’l posa al braç.','Es descorda l’abric per poder caminar.','Deixa l’abric a la vora del camí.','S’agafa l’abric amb més força.'],'d','La reacció del viatger va en sentit contrari al que vol el vent.',[e('vent','El vent va bufar encara més fort. L’home es va agafar l’abric amb més força')]),
      q('canvi','Què fa l’home amb l’abric mentre el Sol l’escalfa, abans de treure-se’l?','Se’l descorda.',['Se’l posa al braç.','Se’l descorda.','Se’l prem contra el cos.','Se’l torna a cordar.'],'b','Descordar-se l’abric és el pas anterior a treure-se’l del tot.',[e('sol','Al cap d’una estona, es va descordar l’abric')]),
      q('calor','Per què el viatger acaba traient-se l’abric?','Perquè té calor després que el Sol hagi escalfat el camí.',['Perquè el vent li ha arrencat els botons.','Perquè vol deixar-lo al Sol perquè s’eixugui.','Perquè té calor després que el Sol hagi escalfat.','Perquè l’abric s’ha enganxat a les branques.'],'c','La calor fa que el viatger decideixi treure’s la peça de roba.',[e('sol','El Sol continuava escalfant'),e('final','«Quina calor!», va dir el viatger. Es va treure l’abric')]),
      q('guanyador','Qui guanya la prova i quin fet ho demostra?','El Sol, perquè l’home es treu l’abric després del seu intent.',['El Sol, perquè l’home es treu l’abric.','El vent, perquè l’home s’agafa l’abric.','El Sol, perquè el vent mou les branques.','El vent, perquè l’home continua caminant.'],'a','El resultat es decideix amb la condició acordada: el viatger es treu l’abric quan actua el Sol.',[e('prova','Guanyarà qui aconsegueixi que aquell home es tregui l’abric'),e('sol','El Sol continuava escalfant'),e('final','Es va treure l’abric')],2)
    ]}),
  cultural({code:'S134',id:'el-pastor-i-el-llop',title:'El pastor i el llop',grade:'4',level:'middle',universeIds:['faules-mon'],
    introduction:'Comprensió oral. El pastor i el llop. Una faula de la tradició d’Isop.',
    summary:'Un jove pastor vigila les ovelles prop del poble. Un dia s’avorreix i decideix cridar els veïns.',
    context:'Escoltaràs una faula sobre un pastor, el seu ramat i els veïns del poble. Els crits del pastor es repeteixen en dies diferents. Fixa’t en què passa en cada ocasió.',
    editorialFocus:'Faules del món. 4t intermèdia: tres moments marcats i un canvi en la confiança dels veïns. Sis preguntes duals sobre motiu, comparació, causa i conseqüència. Perill breu sense detall gràfic; el desenllaç mostra la pèrdua d’una ovella i deixa inferir la moral.',
    factualSources:[{label:'Library of Congress, The Shepherd Boy & the Wolf, dins The Aesop for Children (1919), amb il·lustracions de Milo Winter. Contrast dels dos avisos falsos, l’atac real i la manca de resposta dels veïns.',url:'https://www.loc.gov/static/collections/childrens-book-selections/articles-and-essays/aesop/043.html'}],
    illustrationBrief:'Prat amb un ramat tranquil, un jove pastor amb un bastó i el poble al fons. Sense llop, crits, veïns corrent ni ovelles separades o desaparegudes; no revelar el canvi de confiança ni el desenllaç.',
    transcript:[d('Adaptació original en català de l’argument isòpic contrastat a la Library of Congress. Es conserven dos avisos falsos i un atac real. La pèrdua d’una ovella substitueix la mort de moltes ovelles del testimoni per adequar la intensitat al públic; no s’hi afegeix una sentència moral. Entrada breu d’una base narrativa pròpia, molt suau. Una sola veu per al narrador i els diàlegs citats.'),
      s('avorriment','Narrador','Un jove pastor vigilava les ovelles en un prat prop del poble. Els veïns li havien dit que, si apareixia un llop, cridés i vindrien a ajudar-lo. Aquell matí, el ramat pasturava tranquil. El noi s’avorria. Mirava les cases i pensava què podia fer per distreure’s.'),
      s('primer','Narrador','De sobte, es va posar a cridar: «El llop! Que ve el llop!» Els veïns van deixar la feina i van córrer fins al prat, alguns amb bastons. Quan hi van arribar, el pastor va esclatar a riure. «Us ho heu cregut!», deia. Les ovelles continuaven menjant herba. No hi havia cap llop.'),
      s('segon','Narrador','Uns dies després, el noi va repetir la broma. Va cridar amb totes les seves forces i els veïns van tornar a pujar. Aquesta vegada, quan el van sentir riure, es van enfadar. Havien deixat la feina per una altra alarma inventada. Van girar cua i van tornar al poble.'),
      s('real','Narrador','Una tarda, va sortir un llop d’entre els arbres. El ramat es va escampar pel prat. El noi va córrer cap al camí i va cridar: «El llop! Ajudeu-me! Aquesta vegada és veritat!» Els veïns el van sentir des del poble, però van continuar treballant. «Ja ens vol tornar a enganyar», es deien.'),
      s('final','Narrador','Ningú no va pujar al prat. El llop va atrapar una ovella i se la va endur cap al bosc. El pastor va ajuntar les altres i les va fer baixar pel camí. Aquell vespre caminava darrere del ramat en silenci.'),
      d('Diferenciar els dies amb pauses naturals. Els crits citats es narren amb intenció, sense salts de volum. Cap udol, atac o bel enregistrat que avanci les respostes; conservar la mateixa base molt baixa. Després de silenci, pujar la base dos segons i fondre-la.')],
    items:[
      q('motiu','Per què el pastor inventa el primer avís del llop?','Perquè s’avorreix i vol distreure’s.',['Perquè ha vist el llop entre els arbres.','Perquè s’avorreix i vol distreure’s.','Perquè una ovella ha fugit fins al poble.','Perquè els veïns li han demanat una prova.'],'b','El primer avís neix de l’avorriment, quan el ramat encara està tranquil.',[e('avorriment','El noi s’avorria'),e('avorriment','pensava què podia fer per distreure’s'),e('primer','No hi havia cap llop')]),
      q('primera-resposta','Què fan els veïns quan senten el primer avís?','Deixen la feina i corren fins al prat.',['Esperen que el pastor baixi amb les ovelles.','Continuen treballant perquè no el creuen.','Li demanen que porti el ramat al poble.','Deixen la feina i corren fins al prat.'],'d','Al primer avís, els veïns actuen com havien promès.',[e('primer','Els veïns van deixar la feina i van córrer fins al prat')]),
      q('enfadament','Per què els veïns s’enfaden després del segon avís?','Perquè han tornat a deixar la feina per una alarma inventada.',['Perquè han deixat la feina per una altra alarma inventada.','Perquè el pastor ha fet baixar les ovelles al poble.','Perquè el llop s’ha escapat abans que arribessin.','Perquè cap veí ha portat un bastó al prat.'],'a','Descobreixen que han interromput la feina una altra vegada per la mateixa broma.',[e('segon','Havien deixat la feina per una altra alarma inventada')]),
      q('diferent','Què és diferent quan el pastor crida la tercera vegada?','Aquesta vegada hi ha un llop de debò.',['Aquesta vegada els veïns són al prat.','Aquesta vegada el pastor vol fer una broma.','Aquesta vegada hi ha un llop de debò.','Aquesta vegada les ovelles ja són al poble.'],'c','El tercer avís coincideix amb l’aparició real del llop.',[e('real','Una tarda, va sortir un llop d’entre els arbres')]),
      q('confianca','Per què els veïns no hi van quan el llop apareix de debò?','Perquè els avisos falsos els fan pensar que el pastor els vol enganyar de nou.',['Perquè no senten els crits des del poble.','Perquè creuen que els vol enganyar una altra vegada.','Perquè pensen que el llop ja ha tornat al bosc.','Perquè el pastor els demana que continuïn treballant.'],'b','Han respost als dos avisos falsos i ara interpreten el crit real com una altra broma.',[e('segon','el noi va repetir la broma'),e('real','Els veïns el van sentir des del poble'),e('real','Ja ens vol tornar a enganyar')],2),
      q('consequencia','Què li passa al ramat al final?','El llop s’enduu una ovella i el pastor baixa les altres cap al poble.',['Totes les ovelles se’n van darrere del llop.','Els veïns s’enduen el ramat fins al bosc.','El pastor deixa totes les ovelles al prat.','El llop s’enduu una ovella i el pastor fa baixar les altres.'],'d','La narració tanca amb una pèrdua concreta i el retorn de la resta del ramat.',[e('final','El llop va atrapar una ovella i se la va endur cap al bosc'),e('final','El pastor va ajuntar les altres i les va fer baixar pel camí')],2)
    ]})
];
